import chisel3._
import chisel3.util._

object ForceZero {
  def apply[T <: Data](x: Valid[T]): Valid[T] = {
    val out = Wire(Valid(chiselTypeOf(x.bits)))
    out.valid := x.valid
    out.bits := Mux(x.valid, x.bits, 0.U.asTypeOf(chiselTypeOf(x.bits)))
    out
  }
}

object Zip32 {
  def apply(sz: UInt, a: UInt, b: UInt): UInt = {
    val result = Wire(UInt(64.W))
    result := MuxLookup(sz, 0.U, Seq(
      1.U -> Cat(b(7,0), a(7,0), b(15,8), a(15,8), b(23,16), a(23,16), b(31,24), a(31,24)),
      2.U -> Cat(b(15,0), a(15,0), b(31,16), a(31,16)),
      4.U -> Cat(b, a)
    ))
    result
  }
}

object RotateVectorLeft {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val src = (i + n - shift.asUInt) % n.asUInt
      out(i) := in(src)
    }
    out
  }
}

object RotateVectorRight {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val src = (i + shift.asUInt) % n.asUInt
      out(i) := in(src)
    }
    out
  }
}

object ShiftVectorLeft {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val src = i.U - shift
      out(i).valid := src < n.U && in(src).valid
      out(i).bits := Mux(src < n.U, in(src).bits, 0.U.asTypeOf(chiselTypeOf(in(0).bits)))
    }
    out
  }
}

object ShiftVectorRight {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val src = i.U + shift
      out(i).valid := src < n.U && in(src).valid
      out(i).bits := Mux(src < n.U, in(src).bits, 0.U.asTypeOf(chiselTypeOf(in(0).bits)))
    }
    out
  }
}

object SignExtend {
  def apply(x: UInt, fromWidth: Int, toWidth: Int): UInt = {
    val signBit = x(fromWidth - 1)
    Fill(toWidth - fromWidth, signBit) ## x(fromWidth - 1, 0)
  }
}

object ZeroExtend {
  def apply(x: UInt, toWidth: Int): UInt = {
    Cat(0.U((toWidth - x.getWidth).W), x)
  }
}

