class IndexAllocatorShifting(capacity: Int) extends Module {
  val io = IO(new Bundle {
    val alloc = Decoupled(UInt(log2Ceil(capacity).W))
    val free = Flipped(Decoupled(UInt(log2Ceil(capacity).W)))
  })

  require(capacity > 0)
  val freeList = RegInit(VecInit(Seq.tabulate(capacity)(i => (capacity - 1 - i).U(log2Ceil(capacity).W))))
  val freeCount = RegInit(capacity.U(log2Ceil(capacity + 1).W))

  io.alloc.valid := freeCount > 0.U
  io.alloc.bits := freeList(capacity - 1)

  io.free.ready := freeCount < capacity.U

  when(io.alloc.ready && io.alloc.valid) {
    freeCount := freeCount - 1.U
    for (i <- (capacity - 1) until 0 by -1) {
      freeList(i) := freeList(i - 1)
    }
    freeList(0) := 0.U
  }

  when(io.free.ready && io.free.valid) {
    freeCount := freeCount + 1.U
    for (i <- 0 until (capacity - 1)) {
      freeList(i) := freeList(i + 1)
    }
    freeList(capacity - 1) := io.free.bits
  }

  when(io.alloc.ready && io.alloc.valid && io.free.ready && io.free.valid) {
    freeCount := freeCount
    for (i <- 0 until (capacity - 1)) {
      freeList(i) := freeList(i + 1)
    }
    freeList(capacity - 1) := io.free.bits
  }
}

