class Fifo[T <: Data](gen: T, val entries: Int) extends Module {
  val io = IO(new Bundle {
    val enq = Flipped(Decoupled(gen))
    val deq = Decoupled(gen)
    val count = Output(UInt(log2Ceil(entries + 1).W))
  })

  val mem = Reg(Vec(entries, gen))
  val enq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val deq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val maybe_full = RegInit(false.B)

  val ptr_match = enq_ptr === deq_ptr
  val empty = ptr_match && !maybe_full
  val full = ptr_match && maybe_full

  io.enq.ready := !full
  io.deq.valid := !empty
  io.deq.bits := mem(deq_ptr)
  io.count := Mux(maybe_full && ptr_match, entries.U, Mux(enq_ptr >= deq_ptr, enq_ptr - deq_ptr, enq_ptr + entries.U - deq_ptr))

  when(io.enq.fire && !io.deq.fire) {
    enq_ptr := enq_ptr + 1.U
    maybe_full := true.B
    mem(enq_ptr) := io.enq.bits
  }.elsewhen(!io.enq.fire && io.deq.fire) {
    deq_ptr := deq_ptr + 1.U
    maybe_full := false.B
  }.elsewhen(io.enq.fire && io.deq.fire) {
    enq_ptr := enq_ptr + 1.U
    deq_ptr := deq_ptr + 1.U
    mem(enq_ptr) := io.enq.bits
  }
}

object Fifo {
  def apply[T <: Data](enq: DecoupledIO[T], entries: Int): DecoupledIO[T] = {
    val fifo = Module(new Fifo(chiselTypeOf(enq.bits), entries))
    fifo.io.enq <> enq
    fifo.io.deq
  }
}

