class FifoIxO[T <: Data](gen: T, val entries: Int, val inCount: Int, val outCount: Int) extends Module {
  val io = IO(new Bundle {
    val enq = Vec(inCount, Flipped(Decoupled(gen)))
    val deq = Vec(outCount, Decoupled(gen))
    val count = Output(UInt(log2Ceil(entries + 1).W))
  })

  // Simple implementation using a multi-entry FIFO
  val mem = Reg(Vec(entries, gen))
  val enq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val deq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val count = RegInit(0.U(log2Ceil(entries + 1).W))

  val empty = count === 0.U
  val full = count === entries.U

  for (i <- 0 until outCount) {
    io.deq(i).valid := count > i.U
    io.deq(i).bits := mem((deq_ptr + i.U) % entries.U)
  }

  val enqValid = io.enq.map(_.valid).asUInt
  val enqReady = Wire(Vec(inCount, Bool()))
  val deqReady = io.deq.map(_.ready).asUInt
  val nEnq = PopCount(enqValid)
  val nDeq = PopCount(deqReady)

  for (i <- 0 until inCount) {
    io.enq(i).ready := count + nEnq <= entries.U && enqValid(i)
    // Simpler: just check if FIFO has enough space
    enqReady(i) := count + i.U < entries.U
    io.enq(i).ready := enqReady(i) && enqValid(i)
  }

  // For simplicity, just accept one at a time for now
  // (This is a basic implementation, may need refinement)
  when(!full && io.enq(0).valid) {
    mem(enq_ptr) := io.enq(0).bits
    enq_ptr := enq_ptr + 1.U
    count := count + 1.U
  }

  when(!empty && io.deq(0).ready) {
    deq_ptr := deq_ptr + 1.U
    count := count - 1.U
  }

  io.count := count
}

