class FifoX[T <: Data](gen: T, val entries: Int, val count: Int) extends Module {
  val io = IO(new Bundle {
    val enq = Vec(count, Flipped(Decoupled(gen)))
    val deq = Vec(count, Decoupled(gen))
    val nEnqueued = Output(UInt(log2Ceil(entries + 1).W))
  })

  val mem = Reg(Vec(entries, gen))
  val enq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val deq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val nItems = RegInit(0.U(log2Ceil(entries + 1).W))

  val empty = nItems === 0.U
  val full = nItems === entries.U

  for (i <- 0 until count) {
    io.deq(i).valid := nItems > i.U
    io.deq(i).bits := mem((deq_ptr + i.U) % entries.U)
  }

  for (i <- 0 until count) {
    io.enq(i).ready := nItems + i.U < entries.U || !io.enq(i).valid
  }

  val enqValid = io.enq.map(_.valid).asUInt
  val nEnq = PopCount(enqValid)
  val deqReady = io.deq.map(_.ready).asUInt
  val nDeq = PopCount(deqReady)

  when(nEnq > 0.U || nDeq > 0.U) {
    enq_ptr := (enq_ptr + nEnq) % entries.U
    deq_ptr := (deq_ptr + nDeq) % entries.U
    nItems := nItems + nEnq - nDeq
  }

  for (i <- 0 until count) {
    when(io.enq(i).valid && io.enq(i).ready) {
      mem((enq_ptr + i.U) % entries.U) := io.enq(i).bits
    }
  }

  io.nEnqueued := nItems
}

