class FifoXe[T <: Data](gen: T, val entries: Int, val count: Int) extends Module {
  val io = IO(new Bundle {
    val enq = Flipped(Decoupled(Vec(count, gen)))
    val deq = Decoupled(Vec(count, gen))
    val nEnqueued = Output(UInt(log2Ceil(entries + 1).W))
  })

  val mem = Reg(Vec(entries, Vec(count, gen)))
  val enq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val deq_ptr = RegInit(0.U(log2Ceil(entries).W))
  val nItems = RegInit(0.U(log2Ceil(entries + 1).W))

  val empty = nItems === 0.U
  val full = nItems === entries.U

  io.enq.ready := !full
  io.deq.valid := !empty
  io.deq.bits := mem(deq_ptr)
  io.nEnqueued := nItems

  when(io.enq.fire) {
    mem(enq_ptr) := io.enq.bits
    enq_ptr := enq_ptr + 1.U
    nItems := nItems + 1.U
  }

  when(io.deq.fire) {
    deq_ptr := deq_ptr + 1.U
    nItems := nItems - 1.U
  }
}

