import chisel3._
import chisel3.util._

class IDiv(val xLen: Int) extends Module {
  val io = IO(new Bundle {
    val valid = Input(Bool())
    val ready = Output(Bool())
    val dividend = Input(UInt(xLen.W))
    val divisor = Input(UInt(xLen.W))
    val signed = Input(Bool())
    val quotient = Output(UInt(xLen.W))
    val remainder = Output(UInt(xLen.W))
    val outValid = Output(Bool())
  })

  val sIdle :: sCompute :: sDone :: Nil = Enum(3)
  val state = RegInit(sIdle)
  val count = RegInit(0.U(log2Ceil(xLen + 1).W))

  val dividendReg = Reg(UInt((2 * xLen).W))
  val divisorReg = Reg(UInt(xLen.W))
  val quotientReg = Reg(UInt(xLen.W))
  val signDividend = Reg(Bool())
  val signDivisor = Reg(Bool())

  val absDividend = Mux(io.signed && io.dividend(xLen - 1), (~io.dividend).asUInt + 1.U, io.dividend)
  val absDivisor = Mux(io.signed && io.divisor(xLen - 1), (~io.divisor).asUInt + 1.U, io.divisor)

  io.ready := state === sIdle
  io.quotient := 0.U
  io.remainder := 0.U
  io.outValid := state === sDone

  switch(state) {
    is(sIdle) {
      when(io.valid) {
        state := sCompute
        count := xLen.U
        dividendReg := Cat(0.U(xLen.W), absDividend)
        divisorReg := absDivisor
        signDividend := io.signed && io.dividend(xLen - 1)
        signDivisor := io.signed && io.divisor(xLen - 1)
      }
    }
    is(sCompute) {
      val shifted = dividendReg << 1
      val diff = shifted(2 * xLen - 1, xLen) - divisorReg
      when(diff(xLen - 1)) {
        dividendReg := shifted
      }.otherwise {
        dividendReg := Cat(diff, shifted(xLen - 1, 0))
      }
      count := count - 1.U
      when(count === 0.U) {
        state := sDone
      }
    }
    is(sDone) {
      val unsignedQuotient = dividendReg(xLen - 1, 0)
      val unsignedRemainder = dividendReg(2 * xLen - 1, xLen)
      val signedQuotient = Mux(signDividend ^ signDivisor, (~unsignedQuotient).asUInt + 1.U, unsignedQuotient)
      val signedRemainder = Mux(signDividend, (~unsignedRemainder).asUInt + 1.U, unsignedRemainder)
      io.quotient := Mux(signDividend || signDivisor, signedQuotient, unsignedQuotient)
      io.remainder := Mux(signDividend || signDivisor, signedRemainder, unsignedRemainder)
      state := sIdle
    }
  }
}

