class CoralNPURRArbiter[T <: Data](gen: T, n: Int) extends Module {
  val io = IO(new Bundle {
    val in = Vec(n, Flipped(Decoupled(gen)))
    val out = Decoupled(gen)
    val chosen = Output(UInt(log2Ceil(n).W))
  })

  val lastGrant = RegInit(0.U(log2Ceil(n).W))
  val grant = Wire(UInt(log2Ceil(n).W))
  val grantValid = Wire(Bool())

  val requests = VecInit(io.in.map(_.valid)).asUInt

  // Round-robin priority: start after lastGrant
  val shifted = Cat(requests, requests) >> (lastGrant + 1.U)
  val priority = Mux(shifted > 0.U, lastGrant + 1.U + PriorityEncoder(shifted), PriorityEncoder(requests))

  grantValid := requests.orR
  grant := Mux(grantValid, priority, 0.U)

  io.out.valid := grantValid
  io.out.bits := io.in(grant).bits
  io.chosen := grant

  for (i <- 0 until n) {
    io.in(i).ready := grantValid && grant === i.U && io.out.ready
  }

  when(io.out.fire) {
    lastGrant := grant
  }
}

