class Slice[T <: Data](gen: T, n: Int, start: Int, end: Int) extends Module {
  val io = IO(new Bundle {
    val in = Input(Vec(n, gen))
    val out = Output(Vec(end - start, gen))
  })

  for (i <- start until end) {
    io.out(i - start) := io.in(i)
  }
