class Aligner[T <: Data](gen: T, n: Int) extends Module {
  val io = IO(new Bundle {
    val in = Vec(n, Flipped(Valid(gen)))
    val out = Vec(n, Valid(gen))
  })

  // Count valid inputs
  val validCount = PopCount(io.in.map(_.valid))

  // For each output position, find which input should go there
  for (i <- 0 until n) {
    val found = Wire(Bool())
    val data = Wire(gen)
    found := false.B
    data := 0.U.asTypeOf(gen)

    var seen = 0.U
    for (j <- 0 until n) {
      val isTarget = seen === i.U && io.in(j).valid
      when(isTarget) {
        found := true.B
        data := io.in(j).bits
      }
      seen = seen + io.in(j).valid.asUInt
    }

    io.out(i).valid := found
    io.out(i).bits := data
  }
}

