object Gather {
  def apply[T <: Data](indices: Vec[UInt], data: Vec[T]): Vec[T] = {
    val n = indices.length
    val out = Wire(Vec(n, chiselTypeOf(data(0))))
    for (i <- 0 until n) {
      out(i) := data(indices(i))
    }
    out
  }
}

object Scatter {
  def apply(indicesValid: Vec[Bool], indices: Vec[UInt], data: Vec[UInt]): (Vec[UInt], Vec[Bool], Vec[Bool]) = {
    val n = indices.length
    val result = Wire(Vec(n, UInt(8.W)))
    val writeMask = Wire(Vec(n, Bool()))
    val indicesSelected = Wire(Vec(n, Bool()))

    // Track which output positions have been written
    val written = Wire(Vec(n, Bool()))
    for (i <- 0 until n) {
      written(i) := false.B
    }

    for (i <- 0 until n) {
      result(i) := 0.U
      writeMask(i) := false.B
      indicesSelected(i) := false.B
    }

    for (i <- 0 until n) {
      val idx = indices(i)
      val valid = indicesValid(i)
      val alreadyWritten = VecInit((0 until i).map(j => indicesValid(j) && indices(j) === idx)).asUInt.orR

      when(valid && !alreadyWritten) {
        result(idx) := data(i)
        writeMask(idx) := true.B
        indicesSelected(i) := true.B
      }
    }

    (result, writeMask, indicesSelected)
  }
}

