case class FIFOState[T <: Data](buffer: Vec[T], head: UInt, tail: UInt, count: UInt, capacity: Int, gen: T) {
  def dequeue(n: UInt): FIFOState[T] = {
    val newTail = (tail + n) % capacity.U
    val newCount = count - n
    FIFOState(buffer, head, newTail, newCount, capacity, gen)
  }

  def enqueue(data: Vec[T], n: UInt): FIFOState[T] = {
    val newBuffer = Wire(Vec(capacity, gen))
    for (i <- 0 until capacity) {
      newBuffer(i) := buffer(i)
    }
    for (i <- 0 until capacity) {
      when(i.U < n) {
        val writeIdx = (head + i.U) % capacity.U
        newBuffer(writeIdx) := data(i)
      }
    }
    val newHead = (head + n) % capacity.U
    val newCount = count + n
    FIFOState(newBuffer, newHead, tail, newCount, capacity, gen)
  }

  def flush(): FIFOState[T] = {
    FIFOState(buffer, 0.U, 0.U, 0.U, capacity, gen)
  }

  def peek(n: Int): Vec[T] = {
    val result = Wire(Vec(n, gen))
    for (i <- 0 until n) {
      val idx = (tail + i.U) % capacity.U
      result(i) := buffer(idx)
    }
    result
  }

  def invariant(): Bool = {
    count <= capacity.U
  }
}

object FIFOState {
  def init[T <: Data](capacity: Int, gen: T): FIFOState[T] = {
    val buffer = Wire(Vec(capacity, gen))
    for (i <- 0 until capacity) {
      buffer(i) := 0.U.asTypeOf(gen)
    }
    FIFOState(buffer, 0.U, 0.U, 0.U, capacity, gen)
  }
}

