class CircularBufferMulti[T <: Data](gen: T, val n: Int, val capacity: Int) extends Module {
  val io = IO(new Bundle {
    val enqValid = Input(UInt(log2Ceil(n+1).W))
    val enqData = Input(Vec(n, gen))
    val deqReady = Input(UInt(log2Ceil(n+1).W))
    val flush = Input(Bool())

    val nEnqueued = Output(UInt(log2Ceil(capacity+1).W))
    val dataOut = Output(Vec(n, gen))
  })

  val mem = RegInit(VecInit(Seq.fill(capacity)(0.U.asTypeOf(gen))))
  val head = RegInit(0.U(log2Ceil(capacity).W))
  val tail = RegInit(0.U(log2Ceil(capacity).W))
  val count = RegInit(0.U(log2Ceil(capacity+1).W))

  // Calculate actual dequeue count (limited by count)
  val actualDeq = Wire(UInt(log2Ceil(n+1).W))
  actualDeq := Mux(io.deqReady > count, count, io.deqReady)

  // Calculate actual enqueue count (limited by available space)
  val available = capacity.U - count + actualDeq
  val actualEnq = Wire(UInt(log2Ceil(n+1).W))
  actualEnq := Mux(io.enqValid > available, available, io.enqValid)

  val newTail = (tail + actualDeq) % capacity.U
  val newHead = (head + actualEnq) % capacity.U
  val newCount = count + actualEnq - actualDeq

  // Update tail and count for dequeue
  val nextTail = Wire(UInt(log2Ceil(capacity).W))
  val nextHead = Wire(UInt(log2Ceil(capacity).W))
  val nextCount = Wire(UInt(log2Ceil(capacity+1).W))

  when(io.flush) {
    nextTail := 0.U
    nextHead := 0.U
    nextCount := 0.U
  }.otherwise {
    nextTail := newTail
    nextHead := newHead
    nextCount := newCount
  }

  // Write new data
  for (i <- 0 until n) {
    when(i.U < actualEnq && !io.flush) {
      val writeIdx = (head + i.U) % capacity.U
      mem(writeIdx) := io.enqData(i)
    }
  }

  when(!io.flush) {
    tail := nextTail
    head := nextHead
    count := nextCount
  }.otherwise {
    tail := 0.U
    head := 0.U
    count := 0.U
  }

  io.nEnqueued := count

  for (i <- 0 until n) {
    val idx = (tail + i.U) % capacity.U
    io.dataOut(i) := Mux(i.U < count, mem(idx), 0.U.asTypeOf(gen))
  }
}

