class InstructionBuffer[T <: Data](gen: T, val n: Int, val window: Int) extends Module {
  val io = IO(new Bundle {
    val feedIn = new Bundle {
      val nValid = Input(UInt(log2Ceil(n+1).W))
      val bits = Input(Vec(n, gen))
      val nReady = Output(UInt(log2Ceil(n+1).W))
    }
    val out = Vec(n, Decoupled(gen))
    val nEnqueued = Output(UInt(log2Ceil(window+1).W))
    val nSpace = Output(UInt(log2Ceil(window+1).W))
    val flush = Input(Bool())
  })

  val buffer = RegInit(VecInit(Seq.fill(window)(0.U.asTypeOf(gen))))
  val head = RegInit(0.U(log2Ceil(window).W))
  val tail = RegInit(0.U(log2Ceil(window).W))
  val count = RegInit(0.U(log2Ceil(window+1).W))

  val available = window.U - count
  val actualEnq = Mux(io.feedIn.nValid > available, available, io.feedIn.nValid)
  io.feedIn.nReady := available

  val nDeq = PopCount(io.out.map(_.ready && i.U < count).zipWithIndex.map { case (ready, i) => ready })
  // Actually, the out interface is Decoupled, so we need to set valid and read ready

  val outValid = Wire(Vec(n, Bool()))
  for (i <- 0 until n) {
    outValid(i) := i.U < count
    io.out(i).valid := outValid(i) && !io.flush
    io.out(i).bits := Mux(i.U < count, buffer((tail + i.U) % window.U), 0.U.asTypeOf(gen))
  }

  val actualDeq = PopCount((0 until n).map(i => io.out(i).ready && io.out(i).valid))

  val newTail = (tail + actualDeq) % window.U
  val newHead = (head + actualEnq) % window.U
  val newCount = count + actualEnq - actualDeq

  when(io.flush) {
    head := 0.U
    tail := 0.U
    count := 0.U
  }.otherwise {
    // Write new data
    for (i <- 0 until n) {
      when(i.U < actualEnq) {
        val writeIdx = (head + i.U) % window.U
        buffer(writeIdx) := io.feedIn.bits(i)
      }
    }

    head := newHead
    tail := newTail
    count := newCount
  }

  io.nEnqueued := count
  io.nSpace := window.U - count
}

