object GenerateInterface {
  def generateFieldName(fieldName: String, prefix: String): String = {
    if (prefix.isEmpty) fieldName else s"${prefix}_${fieldName}"
  }

  def generateField(fieldName: String, prefix: String, field: Data, direction: String): String = {
    val fullName = generateFieldName(fieldName, prefix)
    field match {
      case b: Bool =>
        s"  ${direction} logic ${fullName}"
      case u: UInt =>
        val width = if (u.getWidth > 1) s"[${u.getWidth - 1}:0] " else ""
        s"  ${direction} logic ${width}${fullName}"
      case s: SInt =>
        val width = if (s.getWidth > 1) s"[${s.getWidth - 1}:0] " else ""
        s"  ${direction} logic signed ${width}${fullName}"
      case v: Vec[_] =>
        v.zipWithIndex.map { case (elem, i) =>
          generateField(s"${fieldName}_${i}", prefix, elem, direction)
        }.mkString("\n")
      case b: Bundle =>
        b.elements.toSeq.map { case (name, elem) =>
          val elemDir = elem match {
            case d: DecoupledIO[_] => if (d.ready.dir == ActualDirection.Output) "output" else "input"
            case v: ValidIO[_] => if (v.valid.dir == ActualDirection.Output) "output" else "input"
            case _ => direction
          }
          generateField(name, fullName, elem, elemDir)
        }.mkString("\n")
      case d: DecoupledIO[_] =>
        val readyDir = if (direction == "output") "input" else "output"
        val validDir = direction
        Seq(
          generateField("ready", fullName, d.ready, readyDir),
          generateField("valid", fullName, d.valid, validDir),
          generateField("bits", fullName, d.bits, validDir)
        ).mkString("\n")
      case v: ValidIO[_] =>
        val validDir = direction
        Seq(
          generateField("valid", fullName, v.valid, validDir),
          generateField("bits", fullName, v.bits, validDir)
        ).mkString("\n")
      case e: EnumType =>
        val width = if (e.getWidth > 1) s"[${e.getWidth - 1}:0] " else ""
        s"  ${direction} logic ${width}${fullName}"
      case _ =>
        s"  ${direction} logic [${field.getWidth - 1}:0] ${fullName}"
    }
  }

  def apply[T <: Data](io: T, prefix: String): String = {
    io match {
      case b: Bundle =>
        b.elements.toSeq.map { case (name, field) =>
          val direction = field.dir match {
            case ActualDirection.Input => "input"
            case ActualDirection.Output => "output"
            case _ => "output"
          }
          generateField(name, prefix, field, direction)
        }.mkString("\n")
      case _ => ""
    }
  }
}

